# Two-pointer: two sum in sorted array O(n)
def two_sum_sorted(nums: list[int], target: int) -> tuple[int, int] | None:
    left, right = 0, len(nums) - 1
    while left < right:
        current = nums[left] + nums[right]
        if current == target:
            return (left, right)
        elif current < target:
            left += 1
        else:
            right -= 1
    return None

# Two-pointer: remove duplicates from sorted array in-place O(n)
def remove_duplicates(nums: list[int]) -> int:
    if not nums: return 0
    write = 1
    for read in range(1, len(nums)):
        if nums[read] != nums[read - 1]:
            nums[write] = nums[read]
            write += 1
    return write  # new length

# Sliding window: longest substring without repeating characters O(n)
def length_of_longest_substring(s: str) -> int:
    char_index = {}   # last seen index
    max_len = 0
    left = 0
    for right, char in enumerate(s):
        if char in char_index and char_index[char] >= left:
            left = char_index[char] + 1   # shrink window
        char_index[char] = right
        max_len = max(max_len, right - left + 1)
    return max_len

# Sliding window: max sum subarray of fixed size k O(n)
def max_sum_subarray(nums: list[int], k: int) -> int:
    window_sum = sum(nums[:k])
    max_sum = window_sum
    for i in range(k, len(nums)):
        window_sum += nums[i] - nums[i - k]   # slide: add new, remove old
        max_sum = max(max_sum, window_sum)
    return max_sum
